export class Source<T> {
  constructor(private readonly produce: (emit: (value: T) => void) => void) {}
  subscribe(emit: (value: T) => void): void {
    this.produce(emit);
  }
}

export interface Readable<T> {
  read(): T;
}

export type SourceInput<T> =
  | Source<T>
  | Readable<T>
  | PromiseLike<T>
  | ArrayLike<T>
  | Iterable<T>
  | AsyncIterable<T>;

const isArrayLike = <T>(x: any): x is ArrayLike<T> =>
  x && typeof x.length === "number" && typeof x !== "function";
const isPromiseLike = (x: any): x is PromiseLike<any> => typeof x?.then === "function";
const isReadable = (x: any): x is Readable<any> => typeof x?.read === "function";

export function innerFrom<T>(input: SourceInput<T>): Source<T> {
  if (input instanceof Source) return input;
  if (isReadable(input)) return new Source((emit) => emit(input.read()));
  if (isArrayLike(input)) {
    return new Source((emit) => {
      for (let i = 0; i < input.length; i++) emit(input[i]);
    });
  }
  if (isPromiseLike(input)) {
    return new Source((emit) => {
      input.then((v) => emit(v));
    });
  }
  if (Symbol.iterator in (input as object)) {
    return new Source((emit) => {
      for (const v of input as Iterable<T>) emit(v);
    });
  }
  throw new TypeError("not a source input");
}

export function switchEach<T, O extends SourceInput<any>>(
  items: T[],
  project: (value: T) => O,
  emit: (value: unknown) => void,
): void {
  for (const item of items) innerFrom(project(item)).subscribe(emit);
}

export function kind<T>(input: SourceInput<T>): string {
  if (input instanceof Source) return "source";
  if (isArrayLike(input)) return "array-like";
  if (isPromiseLike(input)) return "promise-like";
  return "iterable";
}
